<script setup lang="ts">
import{ref,onMounted,computed}from'vue';import{ShieldCheck,UserRound,History,Save,X}from'@lucide/vue';
const props=defineProps<{staff:any}>(),emit=defineEmits(['unauthorized','pending-change']);
const items=ref<any[]>([]),nextId=ref<string|null>(null),selected=ref(''),detail=ref<any>(null),boot=ref<any>({functionNames:{},clinics:[]}),history=ref<any[]>([]),historyNext=ref<string|null>(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),mode=ref<''|'status'|'grant'>(''),preview=ref<any>(null),pending=ref<any>(null),form=ref<any>({});
const names=computed(()=>boot.value.functionNames||{}),title=(f:string)=>names.value[f]||f,when=(v:any)=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'未登记';
const clinicName=(id:string)=>boot.value.clinics.find((x:any)=>x.id===id)?.name||id.slice(0,8).toUpperCase();
const fieldTitles:Record<string,string>={health:'过敏信息',tags:'患者标签',source:'患者来源',qualification:'证书及附件',quality:'资料检查',patient:'患者',visit:'接诊',appointment:'预约',schedule:'排班',bill:'治疗账单',receipt:'实收',followup:'随访',followup_plan:'随访方案',inventory:'库存',stock:'库存',material:'物资',supplier:'供应商',sale:'商品销售',quarter:'季度核算',expense:'运营费用',clinic:'诊所',dentist:'牙医',security:'系统管理',issue:'专业问题',task:'任务',config:'方案配置',data:'基础资料',identity:'基础身份',arrangement:'安排',contact:'联系登记',arrived_at:'到院时间',started_at:'接诊开始',ended_at:'接诊结束',left_at:'离开时间',profile:'内部资料',skills:'技能',public:'公开介绍',practice:'执业关系',booking_rule:'自助预约规则',issues:'资料问题',status:'账号状态',grant:'授权配置'};
const fieldTitle=(f:any)=>(fieldTitles[f.resource]||f.resource)+' · '+(fieldTitles[f.field]||f.field),fieldKey=(f:any)=>f.resource+':'+f.field+':'+f.action;
const explain=(e:any)=>e.message||'操作失败，请稍后核对。';
async function api(path:string,body?:any){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch('/api/v1/security'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:body?JSON.stringify(body):undefined,signal:controller.signal});const b=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401)emit('unauthorized');throw Object.assign(Error(b.message||'操作未能完成'),{status:r.status});}return b;}finally{clearTimeout(timer);}}
const key=()=>`adc.pendingSecurity:${props.staff.accountId}`;
function keep(p:any){pending.value=p;if(p)sessionStorage.setItem(key(),JSON.stringify(p));else sessionStorage.removeItem(key());emit('pending-change',!!p);}
function recover(){try{const p=JSON.parse(sessionStorage.getItem(key())||'null');if(p&&p.actorAccountId===props.staff.accountId&&/^\/[0-9a-f-]{36}\/(status|grant)$/.test(p.path)&&typeof p.body?.requestId==='string'){pending.value=p;emit('pending-change',true);}}catch{error.value='原提交缓存无法读取，请先核对账号历史。';}}
async function readDetail(id=selected.value){if(!id)return;selected.value=id;detail.value=await api('/'+id);history.value=[];historyNext.value=null;}
async function refresh(){if(loading.value)return;loading.value=true;error.value='';try{boot.value=await api('/bootstrap');const r=await api('');items.value=r.items;nextId.value=r.nextId;const id=items.value.some(x=>x.id===selected.value)?selected.value:items.value[0]?.id;if(id)await readDetail(id);else detail.value=null;}catch(e){error.value=explain(e);}finally{loading.value=false;}}
async function more(){busy.value=true;try{const r=await api('?afterId='+nextId.value);items.value.push(...r.items);nextId.value=r.nextId;}catch(e){error.value=explain(e);}finally{busy.value=false;}}
async function loadHistory(append=false){busy.value=true;error.value='';try{const r=await api('/'+selected.value+'/history'+(append?'?beforeId='+historyNext.value:''));history.value=append?[...history.value,...r.items]:r.items;historyNext.value=r.nextId;if(!r.items.length&&!append)notice.value='此账号尚无本模块办理记录；原开通时间不作为本次管理操作。';}catch(e){error.value=explain(e);}finally{busy.value=false;}}
function open(k:'status'|'grant'){if(pending.value){error.value='请先核实原提交。';return;}mode.value=k;error.value='';preview.value=null;const d=detail.value;form.value={accountVersion:d.account.version,baseGrantId:d.grant?.id||null,enabled:!d.account.enabled,functions:[...(d.grant?.functions||[])],clinicIds:[...(d.grant?.clinicIds||[])],fields:(d.grant?.fields||[]).map((x:any)=>({...x})),reason:'',checked:false};}
function toggleField(f:any,yes:boolean){form.value.fields=yes?[...form.value.fields,{...f}]:form.value.fields.filter((x:any)=>fieldKey(x)!==fieldKey(f));preview.value=null;}
function body(){const f=form.value;return{accountVersion:f.accountVersion,baseGrantId:f.baseGrantId,reason:f.reason,...(mode.value==='status'?{enabled:f.enabled}:{functions:f.functions,clinicIds:f.clinicIds,fields:f.fields})};}
const formSignature=()=>JSON.stringify(body());
async function inspect(){busy.value=true;error.value='';try{const r=await api('/'+selected.value+'/'+mode.value+'/preview',body());preview.value={...r,signature:formSignature()};form.value.checked=false;}catch(e){error.value=explain(e);}finally{busy.value=false;}}
async function submit(p:any){busy.value=true;error.value='';try{const r=await api(p.path,p.body);keep(null);mode.value='';preview.value=null;notice.value=r.repeated?'已核实原提交，未重复另存。':'账号办理已保存，原配置历史保留。';await refresh();await loadHistory();}catch(e:any){error.value=explain(e);if(e.status&&!p.uncertain)keep(null);if(!e.status){p.uncertain=true;keep(p);}if(!e.status)notice.value='提交结果尚不明确，请保留原请求核实；不要另建一次配置。';}finally{busy.value=false;}}
async function save(){if(!preview.value||preview.value.signature!==formSignature()){error.value='填写内容有变化，请重新核对。';return;}if(!form.value.checked){error.value='请明确确认本次账号和变更范围。';return;}const p={actorAccountId:props.staff.accountId,path:'/'+selected.value+'/'+mode.value,body:{...body(),requestId:crypto.randomUUID(),previewToken:preview.value.previewToken,checked:true}};keep(p);await submit(p);}
function clearPermissions(){form.value.functions=[];form.value.clinicIds=[];form.value.fields=[];preview.value=null;}
onMounted(()=>{recover();refresh();});defineExpose({refresh,hasPending:()=>!!pending.value});
</script>
<template><div class="security-workspace"><div v-if="error" class="b-alert error" role="alert">{{error}}</div><div v-if="notice" class="b-alert">{{notice}}</div><div v-if="pending" class="b-card sc-pending"><strong>有一份原账号提交需要核实</strong><p>保持原管理员身份；重试沿用原请求编号和原内容。</p><button class="b-button" :disabled="busy" @click="submit(pending)">核实原提交</button></div>
<section class="b-card sc-head"><div><div class="b-eyebrow">ACCOUNT & ACCESS</div><h2><ShieldCheck :size="25"/>员工账号与权限</h2><p>分别核对账号状态与岗位权限，保留原业务身份和授权版本。</p></div><span class="sc-tag">独立管理权限 · 不开放临床正文</span></section>
<div class="sc-layout"><aside class="b-card sc-list"><h3>已授权管理的账号</h3><button v-for="a in items" :key="a.id" class="sc-person" :class="{active:selected===a.id}" :disabled="loading||busy||!!mode||!!pending" @click="readDetail(a.id).catch(e=>error=explain(e))"><UserRound :size="19"/><span><strong>{{a.employeeName}}</strong><small>{{a.loginName}}</small></span><i :class="{off:a.activation!=='enabled'||a.disabledAt}">{{a.activation==='enabled'&&!a.disabledAt?'启用':'停用'}}</i></button><button v-if="nextId" class="b-button outline full" :disabled="busy||loading" @click="more">继续加载账号</button><p v-if="!items.length&&!loading">当前没有可管理账号。</p></aside>
<div v-if="detail" class="sc-detail"><section class="b-card sc-block"><div class="sc-title"><div><h3>{{detail.account.employeeName}}</h3><p>{{detail.account.loginName}} · 账号版本 {{detail.account.version}}</p></div><button class="b-button outline" :disabled="busy||!!pending" @click="open('status')">{{detail.account.enabled?'停用账号':'恢复账号'}}</button></div><dl class="sc-facts"><div><dt>当前状态</dt><dd>{{detail.account.enabled?'启用':'停用'}}</dd></div><div><dt>原开通时间</dt><dd>{{when(detail.account.openedAt)}}</dd></div><div><dt>最近维护时间</dt><dd>{{when(detail.account.maintainedAt)}}</dd></div><div><dt>员工稳定标识</dt><dd>{{detail.account.employeeId.slice(0,8).toUpperCase()}}</dd></div></dl><p class="b-help">启停不转移员工身份。停用收回现有会话，恢复后须重新登录。</p></section>
<section class="b-card sc-block"><div class="sc-title"><div><h3>当前授权</h3><p>{{detail.grant?'授权版本 '+detail.grant.version+' · 生效 '+when(detail.grant.effectiveFrom):'没有当前授权'}}</p></div><button class="b-button outline" :disabled="busy||!!pending||!detail.limit.grantEditable||detail.grant?.specialObjectScope" @click="open('grant')">调整已有授权</button></div><p v-if="!detail.limit.grantEditable" class="b-help">管理授权由独立配置入口维护，本页面不能转授。</p><p v-if="detail.grant?.specialObjectScope" class="b-help">已有特别对象范围，本批只读保留，不替换为全范围。</p><h4>岗位角色</h4><p>{{detail.grant?.roles.map((x:any)=>x.name).join('、')||'无'}}</p><h4>可办理功能</h4><div class="sc-chips"><span v-for="f in detail.grant?.functions" :key="f">{{title(f)}}</span><small v-if="!detail.grant?.functions.length">无可办理功能</small></div><h4>诊所范围</h4><p>{{detail.grant?.clinicIds.map(clinicName).join('、')||'无'}}</p><h4>可维护字段</h4><div class="sc-chips"><span v-for="f in detail.grant?.fields" :key="fieldKey(f)">{{fieldTitle(f)}}</span><small v-if="!detail.grant?.fields.length">没有字段维护权</small></div></section>
<section class="b-card sc-block"><div class="sc-title"><h3><History :size="20"/>账号办理历史</h3><button class="b-button outline" :disabled="busy||!!pending" @click="loadHistory()">查看历史</button></div><article v-for="h in history" :key="h.id" class="sc-history"><strong>{{h.kind==='security.status.save'?'账号状态':'授权配置'}} · 账号版本 {{h.after.account.version}}</strong><p>{{h.actorName}} · {{when(h.registeredAt)}}</p><p>依据：{{h.reason}}</p><p>状态：{{h.before.account.enabled?'启用':'停用'}} → {{h.after.account.enabled?'启用':'停用'}}</p><p>采用授权：{{h.after.grant?'版本 '+h.after.grant.version:'无'}}</p><details><summary>查看本次采用的完整功能与范围</summary><p>{{h.after.grant?.functions.map(title).join('、')||'无功能'}}</p><p>{{h.after.grant?.clinicIds.map(clinicName).join('、')||'无诊所'}}</p><p>{{h.after.grant?.fields.map(fieldTitle).join('、')||'无字段维护权'}}</p></details></article><button v-if="historyNext" class="b-button outline full" :disabled="busy" @click="loadHistory(true)">继续加载历史</button></section></div></div>
<div v-if="mode" class="b-backdrop"><form class="b-dialog sc-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button type="button" class="b-close" aria-label="关闭账号办理" :disabled="busy||!!pending" @click="mode='' "><X :size="22"/></button><div class="b-eyebrow">REVIEW ACCOUNT CHANGE</div><h2>{{mode==='status'?(form.enabled?'恢复员工账号':'停用员工账号'):'调整已有岗位权限'}}</h2><p>{{detail.account.employeeName}} · {{detail.account.loginName}} · 当前版本 {{detail.account.version}}</p><div v-if="error" class="b-alert error" role="alert">{{error}}</div><template v-if="mode==='status'"><p class="sc-warning">{{form.enabled?'恢复后使用原账号重新登录，原权限仍按当前有效版本检查。':'停用后禁止新的访问并收回现有会话，已有业务记录和员工身份保留。'}}</p></template><template v-else><p>只能从此账号明确批准的范围中选择，不会转授其他岗位权限。</p><fieldset :disabled="busy||!!pending"><legend>可办理功能</legend><label v-for="f in detail.limit.functions" :key="f" class="sc-check"><input type="checkbox" v-model="form.functions" :value="f" @change="preview=null"/>{{title(f)}}</label></fieldset><fieldset :disabled="busy||!!pending"><legend>诊所范围</legend><label v-for="id in detail.limit.clinicIds" :key="id" class="sc-check"><input type="checkbox" v-model="form.clinicIds" :value="id" @change="preview=null"/>{{clinicName(id)}}</label></fieldset><fieldset :disabled="busy||!!pending"><legend>可维护字段</legend><label v-for="f in detail.limit.fields" :key="fieldKey(f)" class="sc-check"><input type="checkbox" :checked="form.fields.some((x:any)=>fieldKey(x)===fieldKey(f))" @change="toggleField(f,($event.target as HTMLInputElement).checked)"/>{{fieldTitle(f)}}</label></fieldset><button type="button" class="b-button outline" :disabled="busy||!!pending" @click="clearPermissions">明确收回全部业务授权</button></template><label class="sc-reason">本次办理依据<textarea v-model="form.reason" required maxlength="1000" rows="2" :disabled="busy||!!pending" @input="preview=null"/></label><button type="button" class="b-button outline full" :disabled="busy||!!pending||!form.reason.trim()" @click="inspect">先检查并核对变更</button><div v-if="preview" class="sc-preview"><strong>本次检查通过</strong><p>{{preview.effect}}</p><p v-if="mode==='grant'">{{form.functions.length}}项功能 · {{form.clinicIds.length}}家诊所 · {{form.fields.length}}项维护字段</p><label class="sc-check"><input type="checkbox" v-model="form.checked" :disabled="busy||!!pending"/>已核对原账号、本次范围及生效影响</label></div><button class="b-button full" :disabled="busy||!!pending||!preview||!form.checked"><Save :size="17"/>确认保存本次变更</button><button v-if="pending" type="button" class="b-button outline full" :disabled="busy" @click="submit(pending)">核实原提交</button></form></div>
</div></template>
<style scoped>.security-workspace{display:grid;grid-template-columns:minmax(0,1fr);gap:24px;min-width:0}.sc-head,.sc-block,.sc-list,.sc-pending{padding:26px}.sc-head,.sc-title{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.sc-head h2,.sc-title h3{display:flex;gap:10px;align-items:center}.sc-head h2{font-size:25px;margin:12px 0}.sc-head p,.sc-title p,.sc-history p{color:#75867c;line-height:1.8}.sc-tag{background:#eef5ef;color:#39715a;border-radius:20px;padding:10px 14px;font-size:12px}.sc-layout{display:grid;grid-template-columns:minmax(230px,300px) minmax(0,1fr);gap:24px;align-items:start}.sc-person{width:100%;display:flex;align-items:center;gap:12px;padding:15px 10px;text-align:left;border:0;border-radius:10px;background:white;margin:8px 0;color:#446253}.sc-person.active{background:#edf4ed}.sc-person span{display:grid;gap:7px;flex:1;min-width:0;overflow-wrap:anywhere}.sc-person small{color:#7c8e82}.sc-person i{font-style:normal;font-size:11px;background:#e7f2e6;padding:5px 8px;border-radius:10px}.sc-person i.off{background:#f2e9e1;color:#9a6a43}.sc-detail{display:grid;min-width:0;gap:24px}.sc-facts{display:grid;grid-template-columns:1fr 1fr;gap:25px}.sc-facts dt{font-size:12px;color:#819187}.sc-facts dd{margin:10px 0 0;overflow-wrap:anywhere}.sc-chips{display:flex;gap:9px;flex-wrap:wrap}.sc-chips span{background:#f0f5ef;border-radius:6px;font-size:12px;padding:8px 10px;color:#5d7766}.sc-block h4{font-size:13px;margin:24px 0 14px;color:#687f70}.sc-block p{line-height:1.8;overflow-wrap:anywhere}.sc-history{border-top:1px solid #e3ebe1;padding:22px 0}.sc-history p{font-size:13px}.sc-dialog{max-width:740px}.sc-dialog p{line-height:1.8}.sc-dialog fieldset{border:1px solid #e2e9e0;border-radius:10px;padding:16px;display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:18px 0}.sc-dialog legend{font-size:13px;color:#5d7567;padding:0 8px}.sc-check{display:flex;align-items:flex-start;gap:9px;line-height:1.7;font-size:13px}.sc-check input{margin-top:5px}.sc-reason{display:grid;gap:10px;margin:22px 0;font-size:14px}.sc-reason textarea{font:inherit;border:1px solid #dce5dc;border-radius:8px;padding:12px}.sc-preview{background:#f1f6ef;padding:18px;border-radius:10px;margin:18px 0}.sc-warning{background:#fbf2e8;padding:18px;border-radius:10px}.sc-dialog>.b-button{margin-top:14px}@media(max-width:900px){.sc-layout{grid-template-columns:minmax(0,1fr)}.sc-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}.sc-list>h3{grid-column:1/-1}}@media(max-width:600px){.sc-head,.sc-list,.sc-block{padding:20px}.sc-list,.sc-facts,.sc-dialog fieldset{grid-template-columns:minmax(0,1fr)}.sc-head h2{font-size:22px}.sc-title .b-button{width:100%}}</style>
